INSERT INTO `categories` (`id`, `parent_id`, `name`, `slug`, `description`, `image_url`, `sort_order`, `is_active`, `created_at`, `updated_at`, `home_status`) VALUES
('a199ad9a-64b8-42e3-b531-0867d9a6760b', 'a199ad9a-64b8-42e3-b531-0867d9a6760b', 'Beauty & Personal Care', 'beauty-personal-care', 'This Hydrating Facial Moisturizer is expertly formulated to deeply nourish and hydrate your skin, providing lasting moisture and a smooth, radiant complexion. Ideal for daily use.', 'https://kolzsticks.github.io/Free-Ecommerce-Products-Api/main/images/products/moisturizer.jpg', 0, 1, '2026-04-21 22:29:06', '2026-04-21 22:29:06', 1),
('a199ad9a-6ef9-4644-9041-354a9e60f608', 'a199ad9a-64b8-42e3-b531-0867d9a6760b', 'Skincare', 'skincare', 'This Hydrating Facial Moisturizer is expertly formulated to deeply nourish and hydrate your skin, providing lasting moisture and a smooth, radiant complexion. Ideal for daily use.', 'https://kolzsticks.github.io/Free-Ecommerce-Products-Api/main/images/products/moisturizer.jpg', 0, 1, '2026-04-21 22:29:06', '2026-04-21 22:29:06', 0),
('a199ad9a-6fe0-488b-9ee8-c17f08b32005', 'a199ad9a-64b8-42e3-b531-0867d9a6760b', 'Hair Care', 'hair-care', 'Our Anti-Dandruff Shampoo effectively combats flakes and itchiness, promoting a healthy scalp. Infused with soothing ingredients, it cleanses your hair without stripping natural oils.', 'https://kolzsticks.github.io/Free-Ecommerce-Products-Api/main/images/products/shampoo.jpg', 0, 1, '2026-04-21 22:29:06', '2026-04-21 22:29:06', 0),
('a199ad9a-7170-4441-9f54-bd557cd028c2', 'a199ad9a-64b8-42e3-b531-0867d9a6760b', 'Makeup', 'makeup', 'This Matte Liquid Foundation offers a flawless finish with long-lasting wear. Lightweight and breathable, it blends seamlessly into the skin, providing even coverage and a natural look.', 'https://kolzsticks.github.io/Free-Ecommerce-Products-Api/main/images/products/foundation.jpg', 0, 1, '2026-04-21 22:29:06', '2026-04-21 22:29:06', 0),
('a199ad9a-7245-48e1-972b-d5564a24ef3f', 'a199ad9a-64b8-42e3-b531-0867d9a6760b', 'Fragrances', 'fragrances', 'Experience the essence of blooming florals with our Eau de Parfum. This captivating scent envelops you in elegance, making it perfect for any occasion, leaving a lasting impression.', 'https://kolzsticks.github.io/Free-Ecommerce-Products-Api/main/images/products/perfume.jpg', 0, 1, '2026-04-21 22:29:06', '2026-04-21 22:29:06', 0),
('a199ad9a-7305-42d8-99af-bb848b5fa0b7', 'a199ad9a-64b8-42e3-b531-0867d9a6760b', 'Grooming', 'grooming', 'This Men\'s Shaving Kit includes everything needed for a close, comfortable shave. Featuring a premium razor and soothing gel, it ensures a smooth experience with every use.', 'https://kolzsticks.github.io/Free-Ecommerce-Products-Api/main/images/products/shaving-kit.jpg', 0, 1, '2026-04-21 22:29:06', '2026-04-21 22:29:06', 0),
('a199ad9a-73b4-4687-81db-48422c6dbea7', 'a199ad9a-64b8-42e3-b531-0867d9a6760b', 'Bath & Body', 'bath-body', 'Our Nourishing Body Wash gently cleanses while replenishing moisture, leaving your skin feeling soft and revitalized. Infused with natural ingredients for a refreshing bathing experience.', 'https://kolzsticks.github.io/Free-Ecommerce-Products-Api/main/images/products/body-wash.jpg', 0, 1, '2026-04-21 22:29:06', '2026-04-21 22:29:06', 0),
('a199ad9a-7470-4da0-a7c8-06ae59dcd36e', 'a199ad9a-64b8-42e3-b531-0867d9a6760b', 'Nail Care', 'nail-care', 'Achieve stunning nails with our Glossy Nail Polish. This vibrant formula provides high shine and long-lasting wear, perfect for expressing your personal style with every application.', 'https://kolzsticks.github.io/Free-Ecommerce-Products-Api/main/images/products/nail-polish.jpg', 0, 1, '2026-04-21 22:29:06', '2026-04-21 22:29:06', 0),
('a199ad9a-75bc-4946-935e-6b1134afec9e', 'a199ad9a-64b8-42e3-b531-0867d9a6760b', 'Men\'s Grooming Products', 'mens-grooming-products', 'The Triple Blade Razor delivers an exceptionally close shave with minimal irritation. Its ergonomic design provides comfort and control, making it a must-have for every grooming routine.', 'https://kolzsticks.github.io/Free-Ecommerce-Products-Api/main/images/products/razor.jpg', 0, 1, '2026-04-21 22:29:06', '2026-04-21 22:29:06', 0),
('a199ad9a-7676-46b8-8fed-04414ea34420', 'a199ad9a-64b8-42e3-b531-0867d9a6760b', 'Health & Wellness Products', 'health-wellness-products', 'Boost your health with our Vitamin C Supplement. Designed to support immune function and overall wellness, these easy-to-take tablets provide essential nutrients for your daily needs.', 'https://kolzsticks.github.io/Free-Ecommerce-Products-Api/main/images/products/vitamin-supplement.jpg', 0, 1, '2026-04-21 22:29:06', '2026-04-21 22:29:06', 0),
('a199ad9a-7713-4c75-a24e-00d2421f7636', 'a199ad9a-64b8-42e3-b531-0867d9a6760b', 'Electronics & Gadgets', 'electronics-gadgets', 'Experience superior sound quality with these wireless Bluetooth headphones, designed for comfort and portability for everyday use.', 'https://kolzsticks.github.io/Free-Ecommerce-Products-Api/main/images/products/wireless-headphones.jpg', 0, 1, '2026-04-21 22:29:06', '2026-04-21 22:29:06', 1),
