('a199ad9a-7851-47dd-9667-1a96a73463fd', 'a199ad9a-7713-4c75-a24e-00d2421f7636', 'Mobile Phones', 'mobile-phones', 'Stay connected with this high-performance smartphone featuring 128GB storage, perfect for apps, photos, and multimedia.', 'https://kolzsticks.github.io/Free-Ecommerce-Products-Api/main/images/products/smartphone.jpg', 0, 1, '2026-04-21 22:29:06', '2026-04-21 22:29:06', 0),
('a199ad9a-78f6-4049-a763-fd9d789bcbe7', 'a199ad9a-7713-4c75-a24e-00d2421f7636', 'Televisions', 'televisions', 'Enjoy breathtaking visuals with this 55-inch 4K Ultra HD TV, delivering stunning detail and vibrant colors for your favorite shows.', 'https://kolzsticks.github.io/Free-Ecommerce-Products-Api/main/images/products/4k-tv.jpg', 0, 1, '2026-04-21 22:29:06', '2026-04-21 22:29:06', 0),
