('a199ad9a-7bf9-47ed-8e7c-b46980198139', 'a199ad9a-7713-4c75-a24e-00d2421f7636', 'Storage', 'storage', 'Store and transfer your files easily with this 64GB USB drive, offering ample space and portability for your data needs.', 'https://kolzsticks.github.io/Free-Ecommerce-Products-Api/main/images/products/usb-drive.jpg', 0, 1, '2026-04-21 22:29:06', '2026-04-21 22:29:06', 0),
('a199ad9a-7c8f-4f2b-9ef3-bd92169b97ef', 'a199ad9a-64b8-42e3-b531-0867d9a6760b', 'Fashion & Apparel', 'fashion-apparel', 'This stylish Men\'s Denim Jacket is perfect for any casual occasion. Crafted from high-quality denim, it features a classic fit, button closure, and timeless design that complements various outfits.', 'https://kolzsticks.github.io/Free-Ecommerce-Products-Api/main/images/products/denim-jacket.jpg', 0, 1, '2026-04-21 22:29:06', '2026-04-21 22:29:06', 1),
('a199ad9a-7d20-450f-8d15-c111fbc4b3f7', 'a199ad9a-7c8f-4f2b-9ef3-bd92169b97ef', 'Men\'s Clothing', 'mens-clothing', 'This stylish Men\'s Denim Jacket is perfect for any casual occasion. Crafted from high-quality denim, it features a classic fit, button closure, and timeless design that complements various outfits.', 'https://kolzsticks.github.io/Free-Ecommerce-Products-Api/main/images/products/denim-jacket.jpg', 0, 1, '2026-04-21 22:29:06', '2026-04-21 22:29:06', 0),
