('a199ad9a-7e4c-492c-8a3e-9f64d19a26c6', 'a199ad9a-7c8f-4f2b-9ef3-bd92169b97ef', 'Footwear', 'footwear', 'These Unisex Casual Sneakers blend comfort and style effortlessly. With a lightweight design and cushioned sole, they\'re perfect for everyday wear, making them a versatile choice for any outfit.', 'https://kolzsticks.github.io/Free-Ecommerce-Products-Api/main/images/products/sneakers.jpg', 0, 1, '2026-04-21 22:29:06', '2026-04-21 22:29:06', 0),
('a199ad9a-7ee6-465e-b3a4-e6c1d5cabb95', 'a199ad9a-7c8f-4f2b-9ef3-bd92169b97ef', 'Accessories', 'accessories', 'Elevate your style with this chic Leather Tote Bag, featuring a spacious interior and elegant design. Crafted from premium leather, it\'s perfect for carrying your essentials while looking effortlessly stylish.', 'https://kolzsticks.github.io/Free-Ecommerce-Products-Api/main/images/products/leather-bag.jpg', 0, 1, '2026-04-21 22:29:06', '2026-04-21 22:29:06', 0),
('a199ad9a-7f81-4ffa-bf89-5c5cd2fc0472', 'a199ad9a-64b8-42e3-b531-0867d9a6760b', 'Home & Kitchen', 'home-kitchen', 'A stylish modern leather sofa that enhances the elegance of your living room while providing utmost comfort for relaxation and entertaining guests.', 'https://kolzsticks.github.io/Free-Ecommerce-Products-Api/main/images/products/sofa.jpg', 0, 1, '2026-04-21 22:29:06', '2026-04-21 22:29:06', 0),
('a199ad9a-801a-40d5-94d2-9298edcfe010', 'a199ad9a-7f81-4ffa-bf89-5c5cd2fc0472', 'Furniture', 'furniture', 'A stylish modern leather sofa that enhances the elegance of your living room while providing utmost comfort for relaxation and entertaining guests.', 'https://kolzsticks.github.io/Free-Ecommerce-Products-Api/main/images/products/sofa.jpg', 0, 1, '2026-04-21 22:29:06', '2026-04-21 22:29:06', 0),
('a199ad9a-80ad-410b-81aa-383a1e6a7f81', 'a199ad9a-7f81-4ffa-bf89-5c5cd2fc0472', 'Kitchen Appliances', 'kitchen-appliances', 'This sleek stainless steel refrigerator features ample storage space, energy efficiency, and modern technology, making it perfect for keeping your food fresh.', 'https://kolzsticks.github.io/Free-Ecommerce-Products-Api/main/images/products/refrigerator.jpg', 0, 1, '2026-04-21 22:29:06', '2026-04-21 22:29:06', 0),
('a199ad9a-8133-48eb-addb-96b5114f0522', 'a199ad9a-7f81-4ffa-bf89-5c5cd2fc0472', 'Home Appliances', 'home-appliances', 'Enjoy effortless cleaning with this cordless vacuum cleaner, designed for convenience and efficiency, easily reaching corners and tight spaces without any cords.', 'https://kolzsticks.github.io/Free-Ecommerce-Products-Api/main/images/products/vacuum-cleaner.jpg', 0, 1, '2026-04-21 22:29:06', '2026-04-21 22:29:06', 0),
